Difficulty based on round number:

  def get_difficulty(round_num):
      if round_num <= 2:
          return 1  # small values, bits only
      elif round_num <= 4:
          return 2  # medium values, bytes
      else:
          return 3  # large values, convert to KB or MB

  def main():
      score = 0
      lives = 3

      for i in range(1, 6):
          diff = get_difficulty(i)
          print(f'Round {i}/5  Lives: {lives}')

          score, lives = play_round(score, lives, diff)

          if lives == 0:
              print('Game over!')
              break

      print(f'Final score: {score}')
